//! Identifier NFC normalization (rustc_parse lexer `nfc_normalize`: identifiers, raw
//! identifiers and lifetimes are compared in Normalization Form C, RFC 2457), UAX #15 over the
//! tables of `nfc_tables` (generated by gen/nfc_tables.py).

use crate::lexer::{Tok, T};
use crate::nfc_tables::{COMBINING_CLASS, COMPOSITION, DECOMPOSITION};

const S_BASE: u32 = 0xAC00;
const L_BASE: u32 = 0x1100;
const V_BASE: u32 = 0x1161;
const T_BASE: u32 = 0x11A7;
const L_COUNT: u32 = 19;
const V_COUNT: u32 = 21;
const T_COUNT: u32 = 28;
const N_COUNT: u32 = V_COUNT * T_COUNT;
const S_COUNT: u32 = L_COUNT * N_COUNT;

fn combining_class(c: u32) -> u8 {
    match COMBINING_CLASS.binary_search_by(|&(first, last, _)| {
        if c < first { std::cmp::Ordering::Greater } else if c > last { std::cmp::Ordering::Less } else { std::cmp::Ordering::Equal }
    }) {
        Ok(i) => COMBINING_CLASS[i].2,
        Err(_) => 0,
    }
}

fn decompose(c: u32, out: &mut Vec<u32>) {
    if (S_BASE..S_BASE + S_COUNT).contains(&c) {
        let s = c - S_BASE;
        out.push(L_BASE + s / N_COUNT);
        out.push(V_BASE + (s % N_COUNT) / T_COUNT);
        if s % T_COUNT != 0 {
            out.push(T_BASE + s % T_COUNT);
        }
        return;
    }
    match DECOMPOSITION.binary_search_by_key(&c, |e| e.0) {
        Ok(i) => {
            for &d in DECOMPOSITION[i].1 {
                decompose(d, out);
            }
        }
        Err(_) => out.push(c),
    }
}

fn compose(a: u32, b: u32) -> Option<u32> {
    if (L_BASE..L_BASE + L_COUNT).contains(&a) && (V_BASE..V_BASE + V_COUNT).contains(&b) {
        return Some(S_BASE + ((a - L_BASE) * V_COUNT + (b - V_BASE)) * T_COUNT);
    }
    if (S_BASE..S_BASE + S_COUNT).contains(&a) && (a - S_BASE) % T_COUNT == 0 && (T_BASE + 1..T_BASE + T_COUNT).contains(&b) {
        return Some(a + (b - T_BASE));
    }
    COMPOSITION.binary_search_by_key(&(a, b), |e| (e.0, e.1)).ok().map(|i| COMPOSITION[i].2)
}

/// The NFC form of `s`.
pub fn nfc(s: &str) -> String {
    let mut d = Vec::with_capacity(s.len());
    for ch in s.chars() {
        decompose(ch as u32, &mut d);
    }
    // canonical ordering: a run of non-starters is stably sorted by combining class
    let mut i = 0;
    while i < d.len() {
        if combining_class(d[i]) == 0 {
            i += 1;
            continue;
        }
        let mut j = i;
        while j < d.len() && combining_class(d[j]) != 0 {
            j += 1;
        }
        d[i..j].sort_by_key(|&c| combining_class(c));
        i = j;
    }
    // canonical composition
    let mut out: Vec<u32> = Vec::with_capacity(d.len());
    let mut starter: Option<usize> = None;
    let mut last_class = 0u8;
    for c in d {
        let class = combining_class(c);
        if let Some(sp) = starter {
            let between = out.len() > sp + 1;
            if !between || last_class < class {
                if let Some(composed) = compose(out[sp], c) {
                    out[sp] = composed;
                    continue;
                }
            }
        }
        if class == 0 {
            starter = Some(out.len());
        }
        last_class = class;
        out.push(c);
    }
    out.into_iter().filter_map(char::from_u32).collect()
}

/// Rewrites the identifiers, raw identifiers and lifetimes of `src` that are not in NFC (only
/// non-ASCII ones can be not), and spells a raw lifetime `'r#a` as `'a` (the same lifetime):
/// the new source, with `toks` adjusted to it, or None when nothing changes.
pub fn normalize_identifiers(src: &[u8], toks: &mut [Tok]) -> Option<Vec<u8>> {
    let ascii = src.is_ascii();
    let mut out: Option<Vec<u8>> = None;
    let mut copied = 0usize;
    let mut delta = 0i64;
    for t in toks.iter_mut() {
        let (lo, hi) = (t.lo as usize, t.hi as usize);
        let candidate = match t.kind {
            T::Lifetime => true,
            T::Ident | T::RawIdent => !ascii,
            _ => false,
        };
        if candidate {
            let lifetime = t.kind == T::Lifetime;
            let mut name_lo = lo + usize::from(lifetime);
            let raw = src[name_lo..hi].starts_with(b"r#");
            if raw { name_lo += 2; }
            let wide = src[name_lo..hi].iter().any(|&b| b >= 0x80);
            if wide || (lifetime && raw) {
                if let Ok(name) = std::str::from_utf8(&src[name_lo..hi]) {
                    let normal = if wide { nfc(name) } else { name.to_string() };
                    // a raw lifetime loses its `r#` (the quote stays)
                    let keep_lo = if lifetime && raw { lo + 1 } else { name_lo };
                    let replaced = &src[keep_lo..hi];
                    if normal.as_bytes() != replaced || (lifetime && raw) {
                        let buf = out.get_or_insert_with(|| Vec::with_capacity(src.len()));
                        buf.extend_from_slice(&src[copied..keep_lo]);
                        buf.extend_from_slice(normal.as_bytes());
                        copied = hi;
                        t.lo = (lo as i64 + delta) as u32;
                        delta += (keep_lo as i64 + normal.len() as i64) - hi as i64;
                        t.hi = (hi as i64 + delta) as u32;
                        continue;
                    }
                }
            }
        }
        t.lo = (lo as i64 + delta) as u32;
        t.hi = (hi as i64 + delta) as u32;
    }
    let mut buf = out?;
    buf.extend_from_slice(&src[copied..]);
    Some(buf)
}

#[cfg(test)]
mod tests {
    use super::nfc;

    #[test]
    fn composes_and_orders() {
        assert_eq!(nfc("Re\u{301}sume\u{301}"), "R\u{e9}sum\u{e9}");
        assert_eq!(nfc("\u{212A}"), "K");
        assert_eq!(nfc("a\u{323}\u{307}"), "\u{1ea1}\u{307}");
        assert_eq!(nfc("a\u{307}\u{323}"), "\u{1ea1}\u{307}");
        assert_eq!(nfc("\u{1100}\u{1161}\u{11a8}"), "\u{ac01}");
        assert_eq!(nfc("\u{ac01}"), "\u{ac01}");
        assert_eq!(nfc("plain"), "plain");
    }
}
